  "BR-DE-17": { severity: "warning", text: "Mit dem Element \"Invoice type code\" (BT-3) sollen ausschließlich folgende Codes aus der Codeliste UNTDID 1001 übermittelt werden: 326 (Partial invoice), 380 (Commercial invoice), 384 (Corrected invoice), 389 (Self-billed invoice) und 381 (Credit note),875 (Partial construction invoice), 876 (Partial final construction invoice), 877 (Final construction invoice)." },
  "BR-DE-18": { severity: "fatal", text: "Skonto Zeilen in <name/> müssen diesem regulärem Ausdruck entsprechen: <value-of select=\"$XR-SKONTO-REGEX\"/>. Die Informationen zur Gewährung von Skonto müssen wie folgt im Element \"Payment terms\" (BT-20) übermittelt werden: Anzugeben ist im ersten Segment \"SKONTO\", im zweiten \"TAGE=n\", im dritten \"PROZENT=n\". Prozentzahlen sind ohne Vorzeichen sowie mit Punkt getrennt von zwei Nachkommastellen anzugeben. Liegt dem zu berechnenden Betrag nicht BT-115, \"fälliger Betrag\" zugrunde, sondern nur ein Teil des fälligen Betrags der Rechnung, ist der Grundwert zur Berechnung von Skonto als viertes Segment \"BASISBETRAG=n\" gemäß dem semantischen Datentypen Amount anzugeben. Jeder Eintrag beginnt mit einer #, die Segmente sind mit einer # getrennt und eine Zeile schließt mit einer # ab. Am Ende einer vollständigen Skontoangabe muss ein XML-konformer Zeilenumbruch folgen. Alle Angaben zur Gewährung von Skonto müssen in Großbuchstaben gemacht werden. Zusätzliches Whitespace (Leerzeichen, Tabulatoren oder Zeilenumbrüche) ist nicht zulässig. Andere Zeichen oder Texte als in den oberen Vorgaben genannt sind nicht zulässig." },
  "BR-DE-21": { severity: "warning", text: "Das Element \"Specification identifier\" (BT-24) soll syntaktisch der Kennung des Standards XRechnung entsprechen." },
  "BR-DE-22": { severity: "fatal", text: "Das \"filename\"-Attribut aller \"EmbeddedDocumentBinaryObject\"-Elemente muss eindeutig sein" },
  "BR-DE-23-a": { severity: "fatal", text: "Wenn BT-81 \"Payment means type code\" einen Schlüssel für Überweisungen enthält (30, 58), muss BG-17 \"CREDIT TRANSFER\" übermittelt werden." },
  "BR-DE-23-b": { severity: "fatal", text: "Wenn BT-81 \"Payment means type code\" einen Schlüssel für Überweisungen enthält (30, 58), dürfen BG-18 und BG-19 nicht übermittelt werden." },
  "BR-DE-24-a": { severity: "fatal", text: "Wenn BT-81 \"Payment means type code\" einen Schlüssel für Kartenzahlungen enthält (48, 54, 55), muss genau BG-18 \"PAYMENT CARD INFORMATION\" übermittelt werden." },
  "BR-DE-24-b": { severity: "fatal", text: "Wenn BT-81 \"Payment means type code\" einen Schlüssel für Kartenzahlungen enthält (48, 54, 55), dürfen BG-17 und BG-19 nicht übermittelt werden." },
  "BR-DE-25-a": { severity: "fatal", text: "Wenn BT-81 \"Payment means type code\" einen Schlüssel für Lastschriften enthält (59), muss genau BG-19 \"DIRECT DEBIT\" übermittelt werden." },
  "BR-DE-25-b": { severity: "fatal", text: "Wenn BT-81 \"Payment means type code\" einen Schlüssel für Lastschriften enthält (59), dürfen BG-17 und BG-18 nicht übermittelt werden." },
  "BR-DE-26": { severity: "warning", text: "Wenn im Element \"Invoice type code\" (BT-3) der Code 384 (Corrected invoice) übergeben wird, soll PRECEDING INVOICE REFERENCE BG-3 mind. einmal vorhanden sein." },
  "BR-DE-27": { severity: "warning", text: "In BT-42 sollen mindestens drei Ziffern enthalten sein." },
  "BR-DE-28": { severity: "warning", text: "In BT-43 soll genau ein @-Zeichen enthalten sein, welches nicht von einem Leerzeichen, einem Punkt, aber mindestens zwei Zeichen auf beiden Seiten flankiert werden soll. Ein Punkt sollte nicht am Anfang oder am Ende stehen." },
  "BR-DE-30": { severity: "fatal", text: "Wenn \"DIRECT DEBIT\" BG-19 vorhanden ist, dann muss \"Bank assigned creditor identifier\" BT-90 übermittelt werden." },
  "BR-DE-31": { severity: "fatal", text: "Wenn \"DIRECT DEBIT\" BG-19 vorhanden ist, dann muss \"Debited account identifier\" BT-91 übermittelt werden." },
  "BR-DE-CVD-01": { severity: "fatal", text: "Das Element <name /> \"Contract reference\" (BT-12) muss übermittelt werden." },
  "BR-DE-CVD-02": { severity: "fatal", text: "Das Element <name /> \"Tender or lot reference\" (BT-17) muss übermittelt werden." },
  "BR-DE-CVD-03": { severity: "fatal", text: "In einer Rechnung muss mindestens eine <name /> INVOICE LINE (BG-25) enthalten sein, in der der Scheme identifier von <name /> \"Item classification identifier\" (BT-158) den Wert 'CVD' und der <name /> \"Item attribute name\" (BT-160) den Wert 'cva' enthält." },
  "BR-DE-CVD-04": { severity: "fatal", text: "Ein <name /> \"Item classification identifier\" (BT-158) mit dem Scheme identifier 'CVD' muss einen Wert aus der Liste der zulässigen Fahrzeugkategorien enthalten." },
  "BR-DE-CVD-05": { severity: "fatal", text: "Wenn innerhalb von <name /> ITEM ATTRIBUTES (BG-32) der <name /> \"Item attribute name\" (BT-160) den Wert 'cva' hat, muss der <name /> \"Item attribute value\" (BT-161) einen der zulässigen Werte enthalten." },
  "BR-DE-CVD-06-a": { severity: "fatal", text: "Wenn der Scheme identifier von <name /> \"Item classification identifier\" (BT-158) mit dem Wert 'CVD' angegeben ist, muss in derselben Rechnungszeile genau ein <name /> \"Item attribute name\" (BT-160) mit dem Wert 'cva' vorhanden sein." },
  "BR-DE-CVD-06-b": { severity: "fatal", text: "Wenn <name /> \"Item attribute name\" (BT-160) mit dem Wert 'cva' angegeben ist, muss in derselben Rechnungszeile genau ein <name /> \"Item classification identifier\" (BT-158) mit dem Scheme identifier 'CVD' vorhanden sein." },
  "BR-DE-TMP-32": { severity: "fatal", text: "Eine Rechnung sollte zur Angabe des Liefer-/Leistungsdatums entweder BT-72 \"Actual delivery date\", BG-14 \"Invoicing period\" oder in jeder Rechnungsposition BG-26 \"Invoice line period\" enthalten." },
  "BR-DEC-01": { severity: "fatal", text: "The allowed maximum number of decimals for the Document level allowance amount (BT-92) is 2." },
  "BR-DEC-02": { severity: "fatal", text: "The allowed maximum number of decimals for the Document level allowance base amount (BT-93) is 2." },
  "BR-DEC-05": { severity: "fatal", text: "The allowed maximum number of decimals for the Document level charge amount (BT-99) is 2." },
  "BR-DEC-06": { severity: "fatal", text: "The allowed maximum number of decimals for the Document level charge base amount (BT-100) is 2." },
  "BR-DEC-09": { severity: "fatal", text: "The allowed maximum number of decimals for the Sum of Invoice line net amount (BT-106) is 2." },
  "BR-DEC-10": { severity: "fatal", text: "The allowed maximum number of decimals for the Sum of allowanced on document level (BT-107) is 2." },
  "BR-DEC-11": { severity: "fatal", text: "The allowed maximum number of decimals for the Sum of charges on document level (BT-108) is 2." },
